function validateRoutineSchedule(value) {
  if (!value || !["daily","interval","weekdays"].includes(value.mode)) throw Error("Ripetizione non valida.");
  const start = value.startDate || "";
  if ((start && validDate(start) !== start) || (value.mode !== "daily" && !start)) throw Error("Data di inizio non valida.");
  const interval = value.mode === "interval" ? value.intervalDays : 1;
  if (!Number.isInteger(interval) || interval < 1 || interval > 365) throw Error("Intervallo non valido.");
  const days = value.mode === "weekdays" ? value.weekdays : [];
  if (!Array.isArray(days) || (value.mode === "weekdays" && !days.length) || days.some(d => !Number.isInteger(d) || d < 1 || d > 7)) throw Error("Giorni non validi.");
  return {mode:value.mode,startDate:start,intervalDays:interval,weekdays:[...new Set(days)].sort()};
}
function routineDue(schedule, day) {
  if (!schedule) return true;
  const s = validateRoutineSchedule(schedule);
  if (s.startDate && day < s.startDate) return false;
  if (s.mode === "daily") return true;
  if (s.mode === "weekdays") return s.weekdays.includes((new Date(day+"T12:00:00Z").getUTCDay()+6)%7+1);
  return Math.round((Date.parse(day+"T12:00:00Z")-Date.parse(s.startDate+"T12:00:00Z"))/86400000)%s.intervalDays === 0;
}

